mapper.select:
SELECT r.id, v.id AS vehicle_id, v.vin, v.lifecycle_stage, a.dealer_id, d.dealer_name, COALESCE(r.stage_status, v.lifecycle_stage) AS stage_status, r.drosstech_status, r.upload_date, r.registration_date, r.customer_region, r.remark8, r.confirmed_by, r.confirmed_at FROM t_vehicle v LEFT JOIN t_veh_registration r ON r.vehicle_id = v.id AND r.deleted = 0 LEFT JOIN t_veh_allocation a ON a.vehicle_id = v.id AND a.deleted = 0 LEFT JOIN t_md_dealer d ON d.id = a.dealer_id AND d.deleted = 0 WHERE v.deleted = 0 AND v.lifecycle_stage = 'PENDING_REGISTRATION'
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
AND a.dealer_id = #{query.dealerId}
AND r.stage_status = #{query.stageStatus}
AND 1 = 0
ORDER BY v.id DESC
